<?php
require_once __DIR__.'/includes/config.php';require_once __DIR__.'/includes/session.php';if(session_status()===PHP_SESSION_NONE)session_start();if(!isset($_SESSION['user_id'])){header('Location: login.php');exit;}$userId=(int)$_SESSION['user_id'];$orderId=(int)($_GET['order_id']??0);function th($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}function label($s){return ucwords(str_replace('_',' ',strtolower((string)$s)));}if($orderId<1){http_response_code(400);die('Invalid order.');}
if(($_GET['ajax']??'')==='location'){header('Content-Type:application/json;charset=utf-8');$out=['ok'=>false,'order_status'=>'','rider'=>null];$s=$conn->prepare('SELECT id,order_status FROM orders WHERE id=? AND user_id=? LIMIT 1');$s->bind_param('ii',$orderId,$userId);$s->execute();$o=$s->get_result()->fetch_assoc();$s->close();if(!$o){echo json_encode($out);exit;}$out['ok']=true;$out['order_status']=$o['order_status'];$sql="SELECT rd.status delivery_status,r.id rider_id,r.full_name rider_name,r.phone rider_phone,r.vehicle_type,r.bike_number,rl.latitude,rl.longitude,rl.updated_at location_updated_at FROM rider_deliveries rd INNER JOIN riders r ON r.id=rd.rider_id LEFT JOIN rider_locations rl ON rl.id=(SELECT x.id FROM rider_locations x WHERE x.rider_id=r.id ORDER BY x.id DESC LIMIT 1) WHERE rd.order_id=? ORDER BY rd.id DESC LIMIT 1";$s=$conn->prepare($sql);if($s){$s->bind_param('i',$orderId);$s->execute();$r=$s->get_result()->fetch_assoc();$s->close();if($r)$out['rider']=$r;}echo json_encode($out);exit;}
$s=$conn->prepare("SELECT o.id,o.order_number,o.order_status,o.created_at,o.total,r.name restaurant_name FROM orders o LEFT JOIN restaurants r ON r.id=o.restaurant_id WHERE o.id=? AND o.user_id=? LIMIT 1");$s->bind_param('ii',$orderId,$userId);$s->execute();$order=$s->get_result()->fetch_assoc();$s->close();if(!$order){http_response_code(404);die('Order not found.');}$status=strtolower(trim($order['order_status']));
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Track Order #<?=th($order['order_number']?:$order['id'])?> | Humsafar</title><link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css"><style>*{box-sizing:border-box}body{margin:0;background:#f7f7f8;color:#222;font-family:Segoe UI,Arial,sans-serif}.wrap{max-width:1000px;margin:30px auto;padding:0 16px 50px}.back{color:#e9003b;text-decoration:none;font-weight:800}.card{margin-top:18px;background:#fff;border:1px solid #eee;border-radius:18px;box-shadow:0 8px 25px #0000000c;overflow:hidden}.head{padding:22px;border-bottom:1px solid #eee;display:flex;justify-content:space-between;gap:15px}.head h1{margin:0}.muted{color:#888;font-size:13px;margin-top:5px}.badge{padding:8px 12px;border-radius:20px;background:#fff0f5;color:#d90038;font-weight:800;font-size:12px;height:max-content}.body{padding:22px}.timeline{display:grid;grid-template-columns:repeat(6,1fr);gap:7px;margin-bottom:24px}.step{text-align:center;color:#999;font-size:11px;font-weight:700}.dot{width:34px;height:34px;margin:0 auto 7px;border-radius:50%;background:#eee;color:#888;display:flex;align-items:center;justify-content:center}.step.done{color:#e9003b}.step.done .dot{background:#e9003b;color:#fff}.waiting{padding:14px;border-radius:11px;background:#fff7df;color:#825a00;font-weight:700;margin-bottom:16px}.delivered{padding:14px;border-radius:11px;background:#eaf9ef;color:#176b35;font-weight:700;margin-bottom:16px}.rider{display:grid;grid-template-columns:300px 1fr;gap:18px}.info{background:#fafafa;border:1px solid #eee;border-radius:13px;padding:17px}.info h2{font-size:18px;margin-top:0}.row{padding:9px 0;border-bottom:1px solid #eee;font-size:12px;color:#777}.row strong{display:block;color:#222;font-size:15px;margin-top:3px}.map{height:430px;border-radius:13px;overflow:hidden;border:1px solid #ddd}@media(max-width:700px){.rider{grid-template-columns:1fr}.timeline{overflow:auto}.step{min-width:80px}.map{height:330px}.head{flex-direction:column}}
</style></head><body><main class="wrap"><a class="back" href="my_orders.php">← My Orders</a><section class="card"><div class="head"><div><h1>Track Order #<?=th($order['order_number']?:$order['id'])?></h1><div class="muted"><?=th($order['restaurant_name']?:'Restaurant')?> · Rs <?=number_format((float)$order['total'],0)?></div></div><span class="badge" id="statusBadge"><?=th(label($status))?></span></div><div class="body"><div class="timeline" id="timeline"><div class="step" data-step="1"><div class="dot">1</div>Placed</div><div class="step" data-step="2"><div class="dot">2</div>Confirmed</div><div class="step" data-step="3"><div class="dot">3</div>Preparing</div><div class="step" data-step="4"><div class="dot">4</div>Rider Assigned</div><div class="step" data-step="5"><div class="dot">5</div>On The Way</div><div class="step" data-step="6"><div class="dot">6</div>Delivered</div></div><div id="message"></div><div class="rider"><div class="info"><h2>Rider Information</h2><div id="riderInfo"><div class="muted">Waiting for a rider to accept your delivery.</div></div></div><div><div class="map" id="map"></div><div class="muted">Rider location refreshes automatically every 5 seconds.</div></div></div></div></section></main><script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script><script>let map=null,marker=null;const orderId=<?=json_encode($orderId)?>,initialStatus=<?=json_encode($status)?>;function stepFor(s){s=(s||'').toLowerCase();if(s==='pending')return 1;if(['confirmed','accepted'].includes(s))return 2;if(s==='preparing')return 3;if(s==='rider_assigned')return 4;if(['picked_up','on_the_way','out_for_delivery','ready','ready_for_pickup'].includes(s))return s==='ready'||s==='ready_for_pickup'?4:5;if(['delivered','completed'].includes(s))return 6;return 1}function updateTimeline(s){const n=stepFor(s);document.querySelectorAll('.step').forEach(x=>x.classList.toggle('done',parseInt(x.dataset.step)<=n))}function esc(v){return String(v??'').replace(/[&<>\'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}function initMap(lat,lng){if(!map){map=L.map('map').setView([lat,lng],15);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap'}).addTo(map);marker=L.marker([lat,lng]).addTo(map)}else{marker.setLatLng([lat,lng]);map.setView([lat,lng])}}function render(d){const s=(d.order_status||'').toLowerCase();document.getElementById('statusBadge').textContent=label(s);updateTimeline(s);const m=document.getElementById('message');m.innerHTML=['delivered','completed'].includes(s)?'<div class="delivered">✓ Your order has been delivered.</div>':d.rider?'':'<div class="waiting">Your food is being prepared. Rider information and live location will appear after a rider accepts the delivery.</div>';const box=document.getElementById('riderInfo');if(d.rider){const r=d.rider;box.innerHTML='<div class="row">Rider<strong>'+esc(r.rider_name||'Rider')+'</strong></div><div class="row">Phone<strong>'+esc(r.rider_phone||'Not available')+'</strong></div><div class="row">Vehicle<strong>'+esc((r.vehicle_type||'Bike')+' '+(r.bike_number||''))+'</strong></div><div class="row">Delivery Status<strong>'+esc(label(r.delivery_status||'accepted'))+'</strong></div><div class="row">Last GPS<strong>'+esc(r.location_updated_at||'Waiting')+'</strong></div>';if(r.latitude!==null&&r.longitude!==null&&!isNaN(parseFloat(r.latitude)))initMap(parseFloat(r.latitude),parseFloat(r.longitude))}}async function poll(){try{const r=await fetch('track-order.php?ajax=location&order_id='+encodeURIComponent(orderId),{cache:'no-store'});const d=await r.json();if(d.ok)render(d)}catch(e){}}updateTimeline(initialStatus);poll();setInterval(poll,5000);</script></body></html>